<?php require 'db.php';$d=body();if(empty($d['username'])||empty($d['password'])){http_response_code(400);echo json_encode(['success'=>false,'message'=>'Username and password are required.']);exit;}try{$s=$pdo->prepare("SELECT u.id,u.first_name,u.last_name,u.student_id,u.username,u.email,u.contact_number,u.role,s.name section_name,d.code program,u.password_hash FROM users u JOIN sections s ON s.id=u.section_id JOIN departments d ON d.id=s.department_id WHERE lower(u.username)=lower(:u)");$s->execute([':u'=>trim($d['username'])]);$u=$s->fetch(PDO::FETCH_ASSOC);if(!$u||!password_verify($d['password'],$u['password_hash'])){http_response_code(401);echo json_encode(['success'=>false,'message'=>'Invalid username or password.']);exit;}unset($u['password_hash']);echo json_encode(['success'=>true,'message'=>'Login successful.','user'=>$u]);}catch(PDOException $e){http_response_code(500);echo json_encode(['success'=>false,'message'=>'Login failed.']);}?>
